CREATE TABLE growing_area_interventions (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id INT UNSIGNED NOT NULL,
    growing_area_code INT UNSIGNED NOT NULL,
    cured_palms_count INT UNSIGNED NOT NULL DEFAULT 0,
    captures_count INT UNSIGNED NOT NULL DEFAULT 0,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    CONSTRAINT fk_growing_area_intervention_user 
        FOREIGN KEY (user_id) REFERENCES users(id) 
        ON DELETE RESTRICT ON UPDATE CASCADE,

    CONSTRAINT fk_interventions_growing_area 
        FOREIGN KEY (growing_area_code) REFERENCES oil_palm_growing_areas(growing_area_code) 
        ON DELETE CASCADE ON UPDATE CASCADE,

    INDEX idx_area_dates (growing_area_code, start_date, end_date),
    INDEX idx_start_date (start_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE strategus_monitorings (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    uuid CHAR(36) NOT NULL UNIQUE,
    user_id INT UNSIGNED NOT NULL,
    growing_area_code INT UNSIGNED DEFAULT NULL,
    location POINT NOT NULL,
    recorded_at DATETIME NOT NULL,
    gallery_count INT UNSIGNED NOT NULL DEFAULT 0,
    gps_accuracy DECIMAL(5, 2) NOT NULL,
    reviewed_at DATETIME NULL DEFAULT NULL,
    synced_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    CONSTRAINT fk_strategus_user 
        FOREIGN KEY (user_id) REFERENCES users(id) 
        ON DELETE RESTRICT ON UPDATE CASCADE,

    CONSTRAINT fk_strategus_growing_area 
        FOREIGN KEY (growing_area_code) REFERENCES oil_palm_growing_areas(growing_area_code) 
        ON DELETE SET NULL ON UPDATE CASCADE,

    SPATIAL INDEX idx_location (location),
    INDEX idx_recorded_at (recorded_at),
    INDEX idx_reviewed_at (reviewed_at),
    INDEX idx_recorded_area (recorded_at, growing_area_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE gps_tracks (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id INT UNSIGNED NOT NULL,
    
    work_date DATE NOT NULL,
    start_time TIME NOT NULL,
    end_time TIME NOT NULL,
    
    trajectory LINESTRING NOT NULL,
    
    synced_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_gps_tracks_user 
        FOREIGN KEY (user_id) REFERENCES users(id) 
        ON DELETE RESTRICT ON UPDATE CASCADE,

    SPATIAL INDEX idx_trajectory (trajectory),
    INDEX idx_user_workdate_time (user_id, work_date, start_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE gps_track_pauses (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id INT UNSIGNED NOT NULL,
    
    pause_date DATE NOT NULL,
    start_time TIME NOT NULL,
    end_time TIME NOT NULL,
    
    location POINT NOT NULL,
    
    synced_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    
    CONSTRAINT fk_track_pauses_user 
        FOREIGN KEY (user_id) REFERENCES users(id) 
        ON DELETE RESTRICT ON UPDATE CASCADE,

    SPATIAL INDEX idx_location (location),
    INDEX idx_user_pause_time (user_id, pause_date, start_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
